// Aggregate all data from parallel fetches
const systemStatus = $('Fetch System Status').first()?.json || {};
const trades = $('Fetch Yesterday Trades').first()?.json?.trades || [];
const agents = $('Fetch Agent Status').first()?.json?.agents || [];
const positions = $('Fetch Open Positions').first()?.json?.positions || [];
const fearGreed = $('Fetch Fear Greed Index').first()?.json?.data?.[0] || {};
const calendar = $('Fetch Economic Calendar').first()?.json || [];

// Calculate trading metrics
const yesterdayPnL = trades.reduce((sum, t) => sum + (parseFloat(t.pnl) || 0), 0);
const winningTrades = trades.filter(t => parseFloat(t.pnl) > 0);
const losingTrades = trades.filter(t => parseFloat(t.pnl) < 0);
const winRate = trades.length > 0 ? (winningTrades.length / trades.length * 100) : 0;
const avgWin = winningTrades.length > 0 ? winningTrades.reduce((s, t) => s + parseFloat(t.pnl), 0) / winningTrades.length : 0;
const avgLoss = losingTrades.length > 0 ? losingTrades.reduce((s, t) => s + parseFloat(t.pnl), 0) / losingTrades.length : 0;

// Calculate agent health
const runningAgents = agents.filter(a => a.status === 'running' || a.status === 'active');
const stoppedAgents = agents.filter(a => a.status === 'stopped' || a.status === 'paused');
const errorAgents = agents.filter(a => a.status === 'error');

// Calculate open exposure
const openExposure = positions.reduce((sum, p) => sum + Math.abs(parseFloat(p.marketValue) || parseFloat(p.notional) || 0), 0);
const unrealizedPnL = positions.reduce((sum, p) => sum + (parseFloat(p.unrealizedPnl) || 0), 0);

// Filter today's high-impact economic events
const today = new Date().toISOString().split('T')[0];
const todayEvents = Array.isArray(calendar) ? calendar.filter(e => {
  const eventDate = e.date?.split(' ')?.[0] || '';
  return eventDate.includes(today.substring(5)) && e.impact === 'High';
}) : [];

// Determine overall system health
let systemHealth = 'HEALTHY';
let healthColor = 3066993; // Green
if (errorAgents.length > 0 || systemStatus.killswitch) {
  systemHealth = 'CRITICAL';
  healthColor = 15158332; // Red
} else if (stoppedAgents.length > agents.length * 0.3) {
  systemHealth = 'DEGRADED';
  healthColor = 16776960; // Yellow
}

// Determine P&L sentiment
let pnlEmoji = '';
let pnlColor = 3066993;
if (yesterdayPnL >= 500) {
  pnlEmoji = ':rocket:';
  pnlColor = 3066993;
} else if (yesterdayPnL >= 0) {
  pnlEmoji = ':white_check_mark:';
  pnlColor = 3066993;
} else if (yesterdayPnL >= -200) {
  pnlEmoji = ':warning:';
  pnlColor = 16776960;
} else {
  pnlEmoji = ':x:';
  pnlColor = 15158332;
}

return {
  json: {
    date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
    timestamp: new Date().toISOString(),

    trading: {
      yesterdayPnL: yesterdayPnL.toFixed(2),
      tradeCount: trades.length,
      winRate: winRate.toFixed(1),
      avgWin: avgWin.toFixed(2),
      avgLoss: avgLoss.toFixed(2),
      pnlEmoji,
      pnlColor
    },

    system: {
      health: systemHealth,
      healthColor,
      killswitchActive: systemStatus.killswitch || false,
      totalAgents: agents.length,
      runningAgents: runningAgents.length,
      stoppedAgents: stoppedAgents.length,
      errorAgents: errorAgents.length,
      agentDetails: agents.map(a => ({ name: a.name, status: a.status }))
    },

    exposure: {
      openPositionCount: positions.length,
      totalExposure: openExposure.toFixed(2),
      unrealizedPnL: unrealizedPnL.toFixed(2)
    },

    market: {
      fearGreedValue: fearGreed.value || 'N/A',
      fearGreedClassification: fearGreed.value_classification || 'N/A',
      todayHighImpactEvents: todayEvents.map(e => `${e.title} (${e.country})`).slice(0, 5)
    },

    rawData: {
      trades: trades.slice(0, 10), // Limit for AI context
      positions,
      agents
    }
  }
};

