// Fallback when data quality check fails
const metrics = $('Calculate Metrics').first()?.json || {};

const fallbackContent = `**SYSTEM STATUS: Data Collection Issue**

Unable to collect complete system data for morning briefing.

**Available Data:**
- Agents detected: ${metrics.system?.totalAgents || 0}
- System health: ${metrics.system?.health || 'UNKNOWN'}

**ACTION REQUIRED:**
1. Check SwjshAK dashboard manually
2. Verify all API endpoints are responding
3. Review agent runner logs for errors

*This is an automated fallback message. Normal briefings will resume when data collection is restored.*`;

return {
  json: {
    content: [{
      type: 'text',
      text: fallbackContent
    }],
    isFallback: true,
    metrics
  }
};

const aiResponse = $json;
const metrics = $('Calculate Metrics').first()?.json;

// Extract briefing text from AI response or fallback
let briefingText = '';
if (aiResponse?.content?.[0]?.text) {
  briefingText = aiResponse.content[0].text;
} else if (aiResponse?.isFallback) {
  briefingText = aiResponse.content?.[0]?.text || 'Briefing generation failed';
}

// Determine embed color based on P&L
let embedColor = 3066993; // Default green
if (metrics?.trading?.pnlColor) {
  embedColor = metrics.trading.pnlColor;
}
if (metrics?.system?.health === 'CRITICAL') {
  embedColor = 15158332; // Red
} else if (metrics?.system?.health === 'DEGRADED') {
  embedColor = 16776960; // Yellow
}

// Build Discord embed structure
const embed = {
  title: `:sunrise: CEO Morning Briefing - ${metrics?.date || new Date().toLocaleDateString()}`,
  description: briefingText.substring(0, 4000), // Discord limit
  color: embedColor,
  fields: [
    {
      name: ':chart_with_upwards_trend: P&L',
      value: `$${metrics?.trading?.yesterdayPnL || '0.00'}`,
      inline: true
    },
    {
      name: ':dart: Win Rate',
      value: `${metrics?.trading?.winRate || '0'}%`,
      inline: true
    },
    {
      name: ':robot: Agents',
      value: `${metrics?.system?.runningAgents || 0}/${metrics?.system?.totalAgents || 0}`,
      inline: true
    },
    {
      name: ':scales: Exposure',
      value: `$${metrics?.exposure?.totalExposure || '0.00'}`,
      inline: true
    },
    {
      name: ':thermometer: Fear/Greed',
      value: `${metrics?.market?.fearGreedValue || 'N/A'} (${metrics?.market?.fearGreedClassification || 'N/A'})`,
      inline: true
    },
    {
      name: ':shield: System',
      value: metrics?.system?.health || 'UNKNOWN',
      inline: true
    }
  ],
  footer: {
    text: 'SwjshAK Autonomous Trading | CEO Briefing v1.0'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    briefingText,
    metrics,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing'
  }
};

